import {commentInput,relationInput} from '../../../shared/src/schemas/discussion.js';
import {readFile} from 'node:fs/promises';
import {query} from '../client.js';
import {issueInput,labelInput} from '../../../shared/src/schemas/issue.js';
export const ISSUE_USAGE=`crew issue list PROJECT [--status ID] [--assignee ID] [--label ID] [--priority N] [--query TEXT]
crew issue create PROJECT --title TEXT [--description TEXT] [--status ID] [--priority N] [--assignee ID] [--estimate N] [--due YYYY-MM-DD] [--parent ID] [--labels ID,ID]
crew issue show ISSUE | edit ISSUE [fields] | delete ISSUE
crew issue labels PROJECT | label-create PROJECT --name TEXT [--color '#abcdef']
crew issue label-edit LABEL [--name TEXT] [--color COLOR] | label-delete LABEL
crew issue comments ISSUE | comment ISSUE --body TEXT [--body-file FILE]
crew issue comment-edit COMMENT --body TEXT | comment-delete COMMENT --yes
crew issue relations ISSUE | relate ISSUE --target ISSUE --kind blocks|duplicates|relates
crew issue unrelate RELATION --yes
crew issue options PROJECT --type users|labels|parents|relations [--issue ID] [--query TEXT] [--selected ID] [--limit N] [--cursor CURSOR]
crew issue children ISSUE [--limit N] [--cursor CURSOR]
crew issue comment-show COMMENT | label-show LABEL
Edits accept --if-revision REVISION from show/comment-show/label-show to reject stale updates.`;
function required(value,name){if(!value)throw new Error('Missing '+name+'\n'+ISSUE_USAGE);return value;}
export async function issueOptions(options,{partial=false}={}) {
  const body={};
  const mapping={title:'title',description:'description',status:'statusId',priority:'priority',assignee:'assigneeId',estimate:'estimate',due:'dueDate',parent:'parentId'};
  for(const [option,field] of Object.entries(mapping))if(Object.hasOwn(options,option))body[field]=['assignee','parent','due','estimate'].includes(option)&&options[option]==='none'?null:options[option];
  if(options['description-file'])body.description=await readFile(options['description-file'],'utf8');
  if(Object.hasOwn(options,'labels'))body.labelIds=options.labels==='none'?[]:String(options.labels).split(',').map(value=>value.trim()).filter(Boolean);
  return issueInput(body,{partial});
}
export async function issueCommand({args,options,client,print}) {
  const [action='list',id]=args;
  if(action==='help'){print(ISSUE_USAGE);return;}
  required(id,action==='list'||action==='create'||action==='labels'||action==='label-create'?'project id':'issue or label id');
  if(action==='list'){print(await client.get('/projects/'+encodeURIComponent(id)+'/issues'+query({statusId:options.status,assigneeId:options.assignee,labelId:options.label,priority:options.priority,q:options.query,limit:options.limit,cursor:options.cursor})));return;}
  if(action==='options'){required(options.type,'--type');print(await client.get('/projects/'+encodeURIComponent(id)+'/issue-options'+query({type:options.type,permission:options.permission,issueId:options.issue,id:options.selected,q:options.query,limit:options.limit,cursor:options.cursor})));return;}
  if(action==='children'){const {issue}=await client.get('/issues/'+encodeURIComponent(id));print(await client.get('/projects/'+issue.projectId+'/issues'+query({parentId:issue.id,limit:options.limit,cursor:options.cursor})));return;}
  if(action==='comment-show'){print(await client.get('/comments/'+encodeURIComponent(id)));return;}
  if(action==='label-show'){print(await client.get('/labels/'+encodeURIComponent(id)));return;}
  const revision=options['if-revision']?{expectedRevision:options['if-revision']}:{};
  if(action==='show'){print(await client.get('/issues/'+encodeURIComponent(id)));return;}
  if(action==='create'){print(await client.post('/projects/'+encodeURIComponent(id)+'/issues',await issueOptions(options)));return;}
  if(action==='edit'){print(await client.patch('/issues/'+encodeURIComponent(id),{...await issueOptions(options,{partial:true}),...revision}));return;}
  if(action==='delete'){
    if(!options.yes)throw new Error('Use --yes to delete an issue');
    print(await client.delete('/issues/'+encodeURIComponent(id)));return;
  }
  if(action==='labels'){print(await client.get('/projects/'+encodeURIComponent(id)+'/labels'+query({q:options.query,limit:options.limit,cursor:options.cursor})));return;}
  if(action==='label-create'){print(await client.post('/projects/'+encodeURIComponent(id)+'/labels',labelInput({name:options.name,color:options.color})));return;}
  if(action==='label-edit'){
    const body={};for(const field of ['name','color'])if(options[field]!==undefined)body[field]=options[field];
    print(await client.patch('/labels/'+encodeURIComponent(id),{...labelInput(body,{partial:true}),...revision}));return;
  }
  if(action==='label-delete'){
    if(!options.yes)throw new Error('Use --yes to delete a label');
    print(await client.delete('/labels/'+encodeURIComponent(id)));return;
  }
  if(action==='comments'){print(await client.get('/issues/'+encodeURIComponent(id)+'/comments'+query({limit:options.limit,cursor:options.cursor})));return;}
  if(action==='comment'||action==='comment-edit'){
    const body=options['body-file']?await readFile(options['body-file'],'utf8'):options.body;
    const input=commentInput({body});
    print(action==='comment'?await client.post('/issues/'+encodeURIComponent(id)+'/comments',input):await client.patch('/comments/'+encodeURIComponent(id),{...input,...revision}));return;
  }
  if(action==='comment-delete'){
    if(!options.yes)throw new Error('Use --yes to delete a comment');
    print(await client.delete('/comments/'+encodeURIComponent(id)));return;
  }
  if(action==='relations'){print(await client.get('/issues/'+encodeURIComponent(id)+'/relations'+query({limit:options.limit,cursor:options.cursor})));return;}
  if(action==='relate'){print(await client.post('/issues/'+encodeURIComponent(id)+'/relations',relationInput({targetIssueId:options.target,kind:options.kind})));return;}
  if(action==='unrelate'){
    if(!options.yes)throw new Error('Use --yes to remove a relation');
    print(await client.delete('/relations/'+encodeURIComponent(id)));return;
  }
  throw new Error('Unknown issue action: '+action+'\n'+ISSUE_USAGE);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
import {createIssue} from '../src/modules/work/issues.js';
async function fixture(fn) {
  const server=await testServer();
  try {
    const request=server.agent();
    const user=(await request('POST','/auth/signup',{name:'Owner',email:'depth@example.test',password:'correct-horse-battery'})).data.user;
    const org=(await request('POST','/orgs',{name:'Depth organization'})).data.organization;
    const project=(await request('POST','/orgs/'+org.id+'/projects',{key:'DEP',name:'Depth project'})).data.project;
    const create=body=>createIssue(server.ctx,{user},project.id,body);
    const options=(type,extra='')=>request('GET','/projects/'+project.id+'/issue-options?type='+type+extra);
    await fn({server,request,user,org,project,create,options});
  }finally{await server.close();}
}
test('parent candidate pages reach beyond 200 and selected lookup resolves independently of search',()=>fixture(async({create,options})=>{
  const first=create({title:'Older than first page'});for(let n=0;n<210;n++)create({title:'Candidate '+n});
  let cursor='',found=false,total=0;
  do{const result=await options('parents','&limit=20'+(cursor?'&cursor='+encodeURIComponent(cursor):''));assert.equal(result.status,200);assert.equal(result.data.total,211);total+=result.data.items.length;found ||= result.data.items.some(item=>item.id===first.id);cursor=result.data.nextCursor;}while(cursor);
  assert.equal(total,211);assert.equal(found,true);
  const selected=await options('parents','&q=does-not-match&id='+first.id);assert.deepEqual(selected.data.items.map(item=>item.id),[first.id]);
}));
test('parent options exclude self and every descendant before matching and pagination',()=>fixture(async({create,options,request,project})=>{
  const root=create({title:'Root'});let node=root;for(let n=0;n<205;n++)node=create({title:'Descendant '+n,parentId:node.id});
  const unrelated=create({title:'Eligible parent'});
  const page=await options('parents','&issueId='+root.id+'&limit=1');assert.deepEqual(page.data.items.map(item=>item.id),[unrelated.id]);assert.equal(page.data.total,1);assert.equal(page.data.nextCursor,null);
  assert.equal((await options('parents','&issueId='+root.id+'&id='+node.id)).data.total,0);
  assert.equal((await request('GET','/projects/'+project.id+'/issues?parentId='+root.id)).data.items.length,1);
}));
test('labels and visible member search reach later records while hiding ungranted guests',()=>fixture(async({server,user,org,project,options,request})=>{
  const db=server.ctx.db,time=server.ctx.now();
  server.ctx.transaction(()=>{
    for(let n=0;n<212;n++){
      const id='member-'+String(n).padStart(3,'0');
      db.prepare('INSERT INTO users (id,email,name,password_hash,created_at,updated_at) SELECT ?,?,?,password_hash,?,? FROM users WHERE id=?').run(id,id+'@example.test','Person '+String(n).padStart(3,'0'),time,time,user.id);
      db.prepare('INSERT INTO memberships (org_id,user_id,role,created_at) VALUES (?,?,?,?)').run(org.id,id,n===211?'guest':'member',time);
      db.prepare('INSERT INTO labels VALUES (?,?,?,?,?,?)').run('label-'+n,project.id,'Label '+String(n).padStart(3,'0'),'#123456',time,time);
    }
  });
  const users=await options('users','&q=Person%20210');assert.equal(users.data.items[0].id,'member-210');assert.equal(users.data.total,1);
  assert.equal((await options('users','&q=Person%20211')).data.total,0);
  await request('POST','/projects/'+project.id+'/guests',{userId:'member-211'});
  assert.equal((await options('users','&id=member-211')).data.total,1);
  const label=await options('labels','&q=Label%20211');assert.equal(label.data.items[0].id,'label-211');
  const later=(await request('GET','/projects/'+project.id+'/labels?q=211')).data;assert.equal(later.items[0].id,'label-211');
}));
test('work-only tokens and granted guest mention flows need no insight permission',()=>fixture(async({request,options,server,org,project})=>{
  const token=(await request('POST','/tokens',{name:'Issue editor',scopes:['issue:write','project:read']})).data.token;
  const response=await request('GET','/projects/'+project.id+'/issue-options?type=users&permission=issue%3Awrite',undefined,{authorization:'Bearer '+token});assert.equal(response.status,200);
  const read=(await request('POST','/tokens',{name:'Read only',scopes:['project:read']})).data.token;
  assert.equal((await request('GET','/projects/'+project.id+'/issue-options?type=parents&permission=issue%3Awrite',undefined,{authorization:'Bearer '+read})).status,403);
  const guest=server.agent(),guestUser=(await guest('POST','/auth/signup',{name:'Visible Guest',email:'guest-depth@example.test',password:'correct-horse-battery'})).data.user;
  await request('POST','/orgs/'+org.id+'/members',{userId:guestUser.id,role:'guest'});
  assert.equal((await guest('GET','/projects/'+project.id+'/issue-options?type=users&permission=comment%3Awrite')).status,403);
  await request('POST','/projects/'+project.id+'/guests',{userId:guestUser.id});
  const visible=await guest('GET','/projects/'+project.id+'/issue-options?type=users&permission=comment%3Awrite');assert.equal(visible.status,200);assert.ok(visible.data.items.some(item=>item.id===guestUser.id));
  assert.equal((await guest('GET','/projects/'+project.id+'/issue-options?type=relations')).status,403);
}));
test('relation lookup crosses eligible same-org projects and excludes self archived and other-org issues',()=>fixture(async({request,org,create,options,project})=>{
  const source=create({title:'Source'});
  const cross=(await request('POST','/orgs/'+org.id+'/projects',{key:'CROSS',name:'Cross project'})).data.project;
  const target=(await request('POST','/projects/'+cross.id+'/issues',{title:'Cross target'})).data.issue;
  const otherOrg=(await request('POST','/orgs',{name:'Other organization'})).data.organization;
  const other=(await request('POST','/orgs/'+otherOrg.id+'/projects',{key:'HIDE',name:'Other project'})).data.project;
  await request('POST','/projects/'+other.id+'/issues',{title:'Other organization target'});
  let result=await options('relations','&issueId='+source.id);assert.deepEqual(result.data.items.map(item=>item.id),[target.id]);
  assert.equal((await request('POST','/issues/'+source.id+'/relations',{kind:'blocks',targetIssueId:target.id})).status,201);
  const inverse=(await request('GET','/issues/'+target.id+'/relations')).data.items[0];assert.equal(inverse.caption,'blocked by');assert.equal(inverse.relatedIssue.id,source.id);
  await request('PATCH','/projects/'+cross.id,{archived:true});result=await options('relations','&issueId='+source.id+'&id='+target.id);assert.equal(result.data.total,0);
  assert.equal((await options('parents','&issueId='+target.id)).status,422);
}));
test('relation lists hide inaccessible endpoints before all cursor pages and counts',()=>fixture(async({request,server,org,project,create})=>{
  const source=create({title:'Source'}),visible=[];
  const privateProject=(await request('POST','/orgs/'+org.id+'/projects',{key:'PRIV',name:'Private project'})).data.project;
  for(let n=0;n<51;n++){const item=create({title:'Related '+n});visible.push(item.id);await request('POST','/issues/'+source.id+'/relations',{kind:'relates',targetIssueId:item.id});}
  const hidden=(await request('POST','/projects/'+privateProject.id+'/issues',{title:'Hidden relation'})).data.issue;
  await request('POST','/issues/'+source.id+'/relations',{kind:'relates',targetIssueId:hidden.id});
  const guest=server.agent(),person=(await guest('POST','/auth/signup',{name:'Reader',email:'reader-depth@example.test',password:'correct-horse-battery'})).data.user;
  await request('POST','/orgs/'+org.id+'/members',{userId:person.id,role:'guest'});await request('POST','/projects/'+project.id+'/guests',{userId:person.id});
  let cursor='',ids=[];do{const page=(await guest('GET','/issues/'+source.id+'/relations?limit=20'+(cursor?'&cursor='+encodeURIComponent(cursor):''))).data;ids.push(...page.items.map(row=>row.relatedIssue.id));cursor=page.nextCursor;}while(cursor);
  assert.equal(ids.length,51);assert.deepEqual(new Set(ids),new Set(visible));assert.ok(!ids.includes(hidden.id));
}));
test('issue revision rejects stale saves without mutation events even when timestamps repeat',()=>fixture(async({server,request,create})=>{
  server.ctx.now=()=> '2026-10-16T00:00:00.000Z';const issue=create({title:'Original'}),events=[];server.ctx.bus.subscribe(event=>events.push(event));
  const changed=await request('PATCH','/issues/'+issue.id,{description:'External',expectedRevision:issue.revision});assert.equal(changed.status,200);assert.notEqual(changed.data.issue.revision,issue.revision);
  const stale=await request('PATCH','/issues/'+issue.id,{title:'Local',expectedRevision:issue.revision});assert.equal(stale.status,409);assert.equal(stale.data.error.details.current.description,'External');assert.equal(events.filter(event=>event.entityType==='issue').length,1);
  const resolved=await request('PATCH','/issues/'+issue.id,{title:'Local',expectedRevision:changed.data.issue.revision});assert.equal(resolved.data.issue.description,'External');assert.equal(resolved.data.issue.title,'Local');
  assert.equal((await request('PATCH','/issues/'+issue.id,{title:'Bad',expectedRevision:1})).status,422);
}));
test('comments and labels expose authorized snapshots and reject stale drafts',()=>fixture(async({request,server,create,project})=>{
  const issue=create({title:'Comment issue'}),comment=(await request('POST','/issues/'+issue.id+'/comments',{body:'Original'})).data.comment;
  const label=(await request('POST','/projects/'+project.id+'/labels',{name:'Original'})).data.label;
  for(const [route,field,record,patch,next] of [['/comments/','comment',comment,{body:'New'},{body:'Stale'}],['/labels/','label',label,{name:'New'},{name:'Stale'}]]){
    assert.deepEqual((await request('GET',route+record.id)).data[field],record);
    const update=await request('PATCH',route+record.id,{...patch,expectedRevision:record.revision});assert.equal(update.status,200);
    const conflict=await request('PATCH',route+record.id,{...next,expectedRevision:record.revision});assert.equal(conflict.status,409);assert.deepEqual(conflict.data.error.details.current,update.data[field]);
    const stranger=server.agent();assert.equal((await stranger('GET',route+record.id)).status,401);
  }
}));
test('candidate validation and archived mutation guards retain stable errors without leaked choices',()=>fixture(async({request,project,options,create})=>{
  const issue=create({title:'Archive source'});
  for(const suffix of ['&limit=201','&cursor=invalid','&q='+encodeURIComponent('x'.repeat(201))])assert.equal((await options('parents',suffix)).status,422);
  assert.equal((await options('unknown')).status,422);
  await request('PATCH','/projects/'+project.id,{archived:true});assert.equal((await options('relations','&issueId='+issue.id)).status,422);
  assert.equal((await request('PATCH','/issues/'+issue.id,{title:'Retained draft',expectedRevision:issue.revision})).status,409);
}));

import {workPickerApi} from './issue-reference.js';
import {useEffect,useMemo,useState} from 'preact/hooks';
import {Button,Notice,Empty,Loading} from '../../components/ui.jsx';
import {EntityPicker} from '../insight/selectors.jsx';
import {createIssuePages} from './issue-paging.js';
export function WorkPicker({api,project,type,issueId,permission='project:read',...props}) {
  const adapter=useMemo(()=>workPickerApi(api,{projectId:project.id,type,issueId,permission}),[api,project.id,type,issueId,permission]);
  return <EntityPicker key={[project.id,type,issueId,permission].join(':')} api={adapter} type={type==='users'?'users':'issues'} orgId={project.orgId} projectId={project.id} permission={permission} {...props}/>;
}
export function useIssuePages(api,route) {
  const [saved,setSaved]=useState(null);
  const owner=useMemo(()=>createIssuePages(cursor=>api.get(route+(route.includes('?')?'&':'?')+new URLSearchParams({limit:20,...(cursor?{cursor}:{})})),state=>setSaved({owner,state})),[api,route]);
  useEffect(()=>{owner.reload();return()=>owner.dispose();},[owner]);
  return {...(saved?.owner===owner?saved.state:owner.snapshot()),more:owner.more,reload:owner.reload};
}
export function PageMore({list,label}) {
  return <><Notice error={list.error}/>{list.loading&&<Loading/>}{list.cursor&&<Button type="button" busy={list.busy} disabled={list.loading} onClick={list.more}>Load more {label}</Button>}<Button type="button" disabled={list.loading||list.busy} onClick={list.reload}>Reload {label}</Button></>;
}
export function LabelSelection({api,project,value,onChange,initial=[]}) {
  const [names,setNames]=useState(()=>Object.fromEntries(initial.map(label=>[label.id,label.name])));
  const selected=value.join(',');
  useEffect(()=>{
    let active=true;
    for(const id of value)if(!names[id])api.get('/labels/'+encodeURIComponent(id)).then(({label})=>{if(active)setNames(previous=>({...previous,[id]:label.name}));},()=>{});
    return()=>{active=false;};
  },[selected,project.id]);
  return <fieldset><legend>Assigned labels ({value.length}/100)</legend>
    {value.length?<ul>{value.map(id=><li key={id}>{names[id]??'Selected label '+id} <Button type="button" onClick={()=>onChange(value.filter(item=>item!==id))}>Remove {names[id]??'label'}</Button></li>)}</ul>:<Empty>No labels selected.</Empty>}
    <WorkPicker api={api} project={project} type="labels" permission="issue:write" label="Add label" value="" disabled={value.length>=100} onChange={(id,item)=>{if(id&&!value.includes(id)){setNames(previous=>({...previous,[id]:item?.name??item?.label}));onChange([...value,id]);}}}/>
  </fieldset>;
}
export function RevisionDecision({error,latest,onInspect,onLoad,onKeep,busy}) {
  if(!error)return null;
  const lost=[401,403,404].includes(error.status);
  return <aside aria-label="Unsaved draft">
    <Notice error={error}/>
    <p>Your draft remains in this form.{lost?' This resource is no longer editable with your current access.':''}</p>
    {onInspect&&<Button type="button" disabled={busy} onClick={onInspect}>Inspect latest version</Button>}
    {latest&&<><pre aria-label="Latest saved version">{JSON.stringify(latest,null,2)}</pre><Button type="button" onClick={()=>{if(globalThis.confirm('Replace your local draft with the latest saved version?'))onLoad(latest);}}>Load latest version</Button>{onKeep&&<Button type="button" onClick={()=>onKeep(latest)}>Keep my changes on latest version</Button>}</>}
  </aside>;
}

export function workPickerApi(api,{projectId,type,issueId,permission='project:read'}) {
  return {get(route){
    const incoming=new URLSearchParams(route.split('?')[1]);
    const query=new URLSearchParams({type,permission});
    if(issueId)query.set('issueId',issueId);
    for(const field of ['q','cursor','limit','id'])if(incoming.get(field))query.set(field,incoming.get(field));
    return api.get('/projects/'+encodeURIComponent(projectId)+'/issue-options?'+query);
  }};
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {createIssuePages} from '../src/pages/work/issue-paging.js';
import {changedFields,issueForm,issuePayload} from '../src/pages/work/issue-state.js';
import {workPickerApi} from '../src/pages/work/issue-reference.js';
const deferred=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return {promise,resolve,reject};};
test('pending issue cursor has one owner and duplicate more clicks do not resend',async()=>{
  const requests=[],a=deferred(),b=deferred();const list=createIssuePages(cursor=>{requests.push(cursor);return requests.length===1?a.promise:b.promise;});
  const first=list.reload();a.resolve({items:[{id:'one'}],nextCursor:'next'});await first;
  const more=list.more();await list.more();assert.deepEqual(requests,[null,'next']);
  b.resolve({items:[{id:'one',title:'fresh'},{id:'two'}],nextCursor:null});await more;
  assert.deepEqual(list.snapshot().items,[{id:'one',title:'fresh'},{id:'two'}]);assert.equal(list.snapshot().busy,false);
});
test('an old issue route response cannot publish after its resource is disposed',async()=>{
  const response=deferred(),seen=[];const old=createIssuePages(()=>response.promise,state=>seen.push(state));
  const pending=old.reload();old.dispose();const current=createIssuePages(async()=>({items:[{id:'current'}],nextCursor:null}));await current.reload();
  const count=seen.length;response.resolve({items:[{id:'wrong-route'}],nextCursor:'bad'});await pending;
  assert.equal(seen.length,count);assert.deepEqual(current.snapshot().items,[{id:'current'}]);
});
test('refresh invalidates a delayed append for a previous filter generation',async()=>{
  const slow=deferred();let calls=0;const list=createIssuePages(()=>++calls===1?Promise.resolve({items:[{id:'old'}],nextCursor:'old-cursor'}):calls===2?slow.promise:Promise.resolve({items:[{id:'new-filter'}],nextCursor:null}));
  await list.reload();const pending=list.more();await list.reload();slow.resolve({items:[{id:'wrong-filter'}],nextCursor:'stale'});await pending;
  assert.deepEqual(list.snapshot().items,[{id:'new-filter'}]);assert.equal(list.snapshot().cursor,null);
});
test('a stale comment failure cannot replace a newer successful load with an error',async()=>{
  const slow=deferred();let calls=0;const list=createIssuePages(()=>++calls===1?slow.promise:Promise.resolve({items:[{id:'new-comment'}],nextCursor:null}));
  const old=list.reload();await list.reload();slow.reject(new Error('old denied'));await old;
  assert.equal(list.snapshot().error,null);assert.equal(list.snapshot().items[0].id,'new-comment');
});
test('pagination failures preserve loaded comments and release busy state for deliberate reload',async()=>{
  let count=0;const list=createIssuePages(async()=>++count===1?{items:[{id:'retained'}],nextCursor:'c'}:{items:[{id:'duplicate'}],nextCursor:'c'});
  await list.reload();await list.more();assert.match(list.snapshot().error.message,/same page cursor/);assert.equal(list.snapshot().items[0].id,'retained');assert.equal(list.snapshot().busy,false);
});
test('issue editor submits changed fields and explicit nulls while preserving concurrent unrelated values on rebase',()=>{
  const before=issuePayload(issueForm({title:'Old',description:'Original',estimate:3,labels:[{id:'a'}]}));
  const draft={...before,title:'My draft',estimate:null};
  const changes=changedFields(before,draft);assert.deepEqual(changes,{title:'My draft',estimate:null});
  const latest={...before,description:'Another person updated this'};assert.equal({...latest,...changes}.description,latest.description);
